/* ========== PASHTOOGLE QUIZ WIDGET CSS ========== */
.pashtoogle-quiz .pq-quiz-container {
  max-width: 100% !important;
  margin: 20px auto !important;
  padding: 24px !important;
  background: #ffffff !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08) !important;
  border-radius: 12px !important;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif !important;
  box-sizing: border-box !important;
}
.pashtoogle-quiz .pq-start-screen {
  text-align: center !important;
  padding: 50px 20px !important;
}
.pashtoogle-quiz .pq-start-screen h1 {
  margin: 0 0 20px 0 !important;
  color: #1a1a2e !important;
  font-size: 32px !important;
  font-weight: 700 !important;
  line-height: 1.3 !important;
}
.pashtoogle-quiz .pq-start-screen p {
  font-size: 18px !important;
  color: #555 !important;
  margin: 0 0 30px 0 !important;
  line-height: 1.7 !important;
}
.pashtoogle-quiz .pq-btn-start {
  display: inline-block !important;
  padding: 14px 48px !important;
  font-size: 19px !important;
  font-weight: 600 !important;
  color: #fff !important;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
  border: none !important;
  border-radius: 50px !important;
  cursor: pointer !important;
  transition: transform 0.2s, box-shadow 0.2s !important;
  text-decoration: none !important;
}
.pashtoogle-quiz .pq-btn-start:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 8px 25px rgba(102, 126, 234, 0.4) !important;
}
.pashtoogle-quiz .pq-btn-start:active {
  transform: translateY(0) !important;
}
.pashtoogle-quiz .pq-quiz-header {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  margin-bottom: 16px !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
}
.pashtoogle-quiz .pq-badge {
  display: inline-block !important;
  padding: 6px 14px !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  border-radius: 20px !important;
  color: #fff !important;
}
.pashtoogle-quiz .pq-badge-secondary {
  background: #6c757d !important;
}
.pashtoogle-quiz .pq-badge-info {
  background: #17a2b8 !important;
}
.pashtoogle-quiz .pq-progress-wrap {
  margin-bottom: 20px !important;
  height: 10px !important;
  background: #e9ecef !important;
  border-radius: 10px !important;
  overflow: hidden !important;
}
.pashtoogle-quiz .pq-progress-bar {
  height: 100% !important;
  background: linear-gradient(90deg, #667eea 0%, #764ba2 100%) !important;
  border-radius: 10px !important;
  transition: width 0.4s ease !important;
}
.pashtoogle-quiz .pq-timer {
  font-size: 32px !important;
  font-weight: 700 !important;
  color: #dc3545 !important;
  text-align: center !important;
  margin-bottom: 20px !important;
  padding: 12px !important;
  background: #fff5f5 !important;
  border-radius: 10px !important;
  border: 2px solid #ffcdd2 !important;
  font-family: 'Courier New', monospace !important;
  letter-spacing: 2px !important;
}
.pashtoogle-quiz .pq-timer.pq-warning {
  color: #ff9800 !important;
  background: #fff8e1 !important;
  border-color: #ffe082 !important;
  animation: pqPulse 1s infinite !important;
}
.pashtoogle-quiz .pq-timer.pq-danger {
  color: #dc3545 !important;
  background: #ffebee !important;
  border-color: #ef9a9a !important;
  animation: pqPulse 0.5s infinite !important;
}
@keyframes pqPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.03); }
  100% { transform: scale(1); }
}
.pashtoogle-quiz .pq-question {
  font-weight: 700 !important;
  margin-bottom: 20px !important;
  font-size: 18px !important;
  color: #1a1a2e !important;
  line-height: 1.5 !important;
}
.pashtoogle-quiz .pq-options {
  display: flex !important;
  flex-direction: column !important;
  gap: 10px !important;
}
.pashtoogle-quiz .pq-options button {
  display: block !important;
  width: 100% !important;
  padding: 14px 18px !important;
  margin: 0 !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  text-align: left !important;
  color: #495057 !important;
  background: #fff !important;
  border: 2px solid #dee2e6 !important;
  border-radius: 10px !important;
  cursor: pointer !important;
  transition: all 0.25s ease !important;
  box-sizing: border-box !important;
  line-height: 1.4 !important;
}
.pashtoogle-quiz .pq-options button:hover:not(:disabled) {
  background: #f8f9fa !important;
  border-color: #667eea !important;
  color: #667eea !important;
  transform: translateX(4px) !important;
}
.pashtoogle-quiz .pq-options button:disabled {
  cursor: not-allowed !important;
  opacity: 0.85 !important;
}
.pashtoogle-quiz .pq-options button.pq-correct {
  background-color: #d4edda !important;
  color: #155724 !important;
  border-color: #28a745 !important;
  font-weight: 600 !important;
}
.pashtoogle-quiz .pq-options button.pq-correct::after {
  content: " ✓" !important;
  float: right !important;
  font-weight: 700 !important;
}
.pashtoogle-quiz .pq-options button.pq-incorrect {
  background-color: #f8d7da !important;
  color: #721c24 !important;
  border-color: #dc3545 !important;
  text-decoration: line-through !important;
}
.pashtoogle-quiz .pq-options button.pq-incorrect::after {
  content: " ✗" !important;
  float: right !important;
  font-weight: 700 !important;
}
.pashtoogle-quiz .pq-explanation-btn {
  display: inline-block !important;
  margin-top: 16px !important;
  padding: 8px 20px !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  color: #fff !important;
  background: #17a2b8 !important;
  border: none !important;
  border-radius: 6px !important;
  cursor: pointer !important;
  transition: background 0.2s !important;
}
.pashtoogle-quiz .pq-explanation-btn:hover {
  background: #138496 !important;
}
.pashtoogle-quiz .pq-explanation {
  background-color: #e7f3ff !important;
  padding: 16px !important;
  border-left: 4px solid #007bff !important;
  margin-top: 12px !important;
  display: none !important;
  border-radius: 0 8px 8px 0 !important;
  color: #004085 !important;
  font-size: 15px !important;
  line-height: 1.6 !important;
}
.pashtoogle-quiz .pq-next-wrap {
  margin-top: 20px !important;
  text-align: right !important;
}
.pashtoogle-quiz .pq-btn-next {
  display: inline-block !important;
  padding: 12px 32px !important;
  font-size: 16px !important;
  font-weight: 600 !important;
  color: #fff !important;
  background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%) !important;
  border: none !important;
  border-radius: 8px !important;
  cursor: pointer !important;
  transition: all 0.2s !important;
}
.pashtoogle-quiz .pq-btn-next:hover:not(:disabled) {
  transform: translateY(-2px) !important;
  box-shadow: 0 6px 20px rgba(17, 153, 142, 0.3) !important;
}
.pashtoogle-quiz .pq-btn-next:disabled {
  background: #adb5bd !important;
  cursor: not-allowed !important;
  transform: none !important;
  box-shadow: none !important;
}
.pashtoogle-quiz .pq-result-card {
  text-align: center !important;
  padding: 40px 20px !important;
}
.pashtoogle-quiz .pq-result-card h2 {
  margin: 0 0 20px 0 !important;
  color: #1a1a2e !important;
  font-size: 29px !important;
}
.pashtoogle-quiz .pq-score-display {
  font-size: 56px !important;
  font-weight: 800 !important;
  margin: 20px 0 !important;
  color: #1a1a2e !important;
  line-height: 1 !important;
}
.pashtoogle-quiz .pq-score-display span {
  color: #667eea !important;
}
.pashtoogle-quiz .pq-percentage {
  font-size: 21px !important;
  color: #555 !important;
  margin-bottom: 20px !important;
}
.pashtoogle-quiz .pq-remarks {
  font-size: 21px !important;
  font-weight: 700 !important;
  padding: 18px 24px !important;
  border-radius: 12px !important;
  margin: 20px auto 0 auto !important;
  max-width: 400px !important;
  line-height: 1.4 !important;
}
.pashtoogle-quiz .pq-remarks.pq-excellent {
  background: #d4edda !important;
  color: #155724 !important;
  border: 2px solid #28a745 !important;
}
.pashtoogle-quiz .pq-remarks.pq-good {
  background: #d1ecf1 !important;
  color: #0c5460 !important;
  border: 2px solid #17a2b8 !important;
}
.pashtoogle-quiz .pq-remarks.pq-average {
  background: #fff3cd !important;
  color: #856404 !important;
  border: 2px solid #ffc107 !important;
}
.pashtoogle-quiz .pq-remarks.pq-poor {
  background: #f8d7da !important;
  color: #721c24 !important;
  border: 2px solid #dc3545 !important;
}
.pashtoogle-quiz .pq-btn-restart {
  display: inline-block !important;
  margin-top: 30px !important;
  padding: 14px 40px !important;
  font-size: 18px !important;
  font-weight: 600 !important;
  color: #fff !important;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
  border: none !important;
  border-radius: 50px !important;
  cursor: pointer !important;
  transition: transform 0.2s, box-shadow 0.2s !important;
}
.pashtoogle-quiz .pq-btn-restart:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 8px 25px rgba(102, 126, 234, 0.4) !important;
}
.pashtoogle-quiz .pq-error {
  padding: 20px !important;
  background: #f8d7da !important;
  color: #721c24 !important;
  border: 1px solid #f5c6cb !important;
  border-radius: 8px !important;
  text-align: center !important;
  font-weight: 500 !important;
}
.pashtoogle-quiz .pq-hidden {
  display: none !important;
}
.pashtoogle-quiz {
  -webkit-user-select: none !important;
  -moz-user-select: none !important;
  -ms-user-select: none !important;
  user-select: none !important;
}
@media (max-width: 768px) {
  .pashtoogle-quiz .pq-quiz-container {
    padding: 16px !important;
    margin: 10px auto !important;
  }
  .pashtoogle-quiz .pq-start-screen {
    padding: 30px 15px !important;
  }
  .pashtoogle-quiz .pq-start-screen h1 {
    font-size: 24px !important;
  }
  .pashtoogle-quiz .pq-timer {
    font-size: 24px !important;
    padding: 10px !important;
  }
  .pashtoogle-quiz .pq-score-display {
    font-size: 40px !important;
  }
  .pashtoogle-quiz .pq-question {
    font-size: 16px !important;
  }
  .pashtoogle-quiz .pq-options button {
    padding: 12px 14px !important;
    font-size: 15px !important;
  }
}

js:
(function() {
  'use strict';
  var widgets = document.querySelectorAll('.pashtoogle-quiz');
  if (widgets.length === 0) return;
  var widget = widgets[widgets.length - 1];
  var BUNDLE_URL = widget.getAttribute('data-bundle-url');
  var SUBJECT_KEY = widget.getAttribute('data-subject-key');
  var SUBJECT = widget.getAttribute('data-subject') || 'Quiz';
  var TIMER_SECONDS = parseInt(widget.getAttribute('data-timer')) || 60;
  var quizData = [];
  var currentQuestion = 0;
  var score = 0;
  var timerInterval = null;
  var timeLeft = 0;
  var answered = false;
  function $id(id) { return widget.querySelector('#' + id); }
  var titleEl = widget.querySelector('.pq-subject-title');
  if (titleEl) titleEl.textContent = SUBJECT;
  var timerPerQEl = widget.querySelector('.pq-timer-per-q');
  if (timerPerQEl) timerPerQEl.textContent = Math.ceil(TIMER_SECONDS / 60);
  function loadBundle() {
    if (!BUNDLE_URL || !SUBJECT_KEY) {
      showError('Please set data-bundle-url and data-subject-key attributes.');
      return;
    }
    var xhr = new XMLHttpRequest();
    xhr.open('GET', BUNDLE_URL + '?t=' + Date.now(), true);
    xhr.onreadystatechange = function() {
      if (xhr.readyState === 4) {
        if (xhr.status === 200) {
          try {
            var bundle = JSON.parse(xhr.responseText);
            // Inject CSS
            if (bundle.css) {
              var style = document.createElement('style');
              style.textContent = bundle.css;
              document.head.appendChild(style);
            }
            // Load quiz data
            var jsonData = bundle[SUBJECT_KEY];
            if (!jsonData) {
              showError('Subject key "' + SUBJECT_KEY + '" not found in bundle.');
              return;
            }
            quizData = [];
            for (var i = 0; i < jsonData.length; i++) {
              var item = jsonData[i];
              quizData.push({
                qNo: parseInt(item["Q.No"]),
                question: item["Question"],
                options: [item["Option A"], item["Option B"], item["Option C"], item["Option D"]],
                correct: item["Correct Option"].charCodeAt(0) - 65,
                explanation: item["Explanation"]
              });
            }
            var totalQ = quizData.length;
            var totalEls = widget.querySelectorAll('.pq-total-questions, #pqTotalQ, #pqTotalCount');
            for (var j = 0; j < totalEls.length; j++) {
              totalEls[j].textContent = totalQ;
            }
          } catch (e) {
            showError('Error parsing bundle: ' + e.message);
          }
        } else {
          showError('Failed to load bundle. Status: ' + xhr.status);
        }
      }
    };
    xhr.onerror = function() {
      showError('Network error. Please check your bundle URL.');
    };
    xhr.send();
  }
  function showError(msg) {
    var startScreen = $id('pqStartScreen');
    if (startScreen) {
      startScreen.innerHTML = '<div class="pq-error">' + msg + '</div>';
    }
  }
  window.pqStartQuiz = function() {
    if (quizData.length === 0) return;
    $id('pqStartScreen').classList.add('pq-hidden');
    $id('pqQuizScreen').classList.remove('pq-hidden');
    $id('pqResultScreen').classList.add('pq-hidden');
    currentQuestion = 0;
    score = 0;
    $id('pqCurrentScore').textContent = '0';
    showQuestion();
  };
  function showQuestion() {
    answered = false;
    var data = quizData[currentQuestion];
    $id('pqCurrentQ').textContent = currentQuestion + 1;
    var progress = ((currentQuestion) / quizData.length) * 100;
    $id('pqProgressBar').style.width = progress + '%';
    var quizContainer = $id('pqQuiz');
    var optionsHtml = '';
    for (var i = 0; i < data.options.length; i++) {
      optionsHtml += '<button class="" id="pq-opt-' + i + '" onclick="pqCheckAnswer(this, ' + currentQuestion + ', ' + i + ')">' + data.options[i] + '</button>';
    }
    quizContainer.innerHTML = 
      '<div class="mb-4">' +
        '<div class="pq-question">' + data.qNo + '. ' + data.question + '</div>' +
        '<div class="pq-options">' + optionsHtml + '</div>' +
        '<button class="pq-explanation-btn pq-hidden" id="pqExpBtn" onclick="pqToggleExplanation()">Show Explanation</button>' +
        '<div class="pq-explanation pq-hidden" id="pqExplanation">' + data.explanation + '</div>' +
        '<div class="pq-next-wrap">' +
          '<button class="pq-btn-next" id="pqNextBtn" onclick="pqNextQuestion()" disabled>Next ➜</button>' +
        '</div>' +
      '</div>';
    startTimer();
  }
  function startTimer() {
    timeLeft = TIMER_SECONDS;
    updateTimerDisplay();
    var timerEl = $id('pqTimer');
    timerEl.classList.remove('pq-warning', 'pq-danger');
    if (timerInterval) clearInterval(timerInterval);
    timerInterval = setInterval(function() {
      timeLeft--;
      updateTimerDisplay();
      if (timeLeft <= 20 && timeLeft > 10) {
        timerEl.classList.add('pq-warning');
      } else if (timeLeft <= 10) {
        timerEl.classList.remove('pq-warning');
        timerEl.classList.add('pq-danger');
      }
      if (timeLeft <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
        timeUp();
      }
    }, 1000);
  }
  function updateTimerDisplay() {
    var minutes = Math.floor(timeLeft / 60);
    var seconds = timeLeft % 60;
    $id('pqTimer').textContent = 
      (minutes < 10 ? '0' : '') + minutes + ':' + (seconds < 10 ? '0' : '') + seconds;
  }
  function timeUp() {
    if (!answered) {
      var buttons = widget.querySelectorAll('.pq-options button');
      var correctIndex = quizData[currentQuestion].correct;
      for (var i = 0; i < buttons.length; i++) {
        buttons[i].disabled = true;
        if (i === correctIndex) {
          buttons[i].classList.add('pq-correct');
        }
      }
      $id('pqExpBtn').classList.remove('pq-hidden');
      $id('pqNextBtn').disabled = false;
      answered = true;
    }
  }
  window.pqCheckAnswer = function(btn, questionIndex, optionIndex) {
    if (answered) return;
    answered = true;
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    var parent = btn.parentNode;
    var buttons = parent.querySelectorAll('button');
    var correctIndex = quizData[questionIndex].correct;
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].disabled = true;
    }
    if (optionIndex === correctIndex) {
      btn.classList.add('pq-correct');
      score++;
      $id('pqCurrentScore').textContent = score;
    } else {
      btn.classList.add('pq-incorrect');
      buttons[correctIndex].classList.add('pq-correct');
    }
    $id('pqExpBtn').classList.remove('pq-hidden');
    $id('pqNextBtn').disabled = false;
  };
  window.pqToggleExplanation = function() {
    var btn = $id('pqExpBtn');
    var explanationDiv = $id('pqExplanation');
    if (!btn || !explanationDiv) return;
    if (explanationDiv.classList.contains('pq-hidden')) {
      explanationDiv.classList.remove('pq-hidden');
      btn.textContent = 'Hide Explanation';
    } else {
      explanationDiv.classList.add('pq-hidden');
      btn.textContent = 'Show Explanation';
    }
  };
  window.pqNextQuestion = function() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    currentQuestion++;
    if (currentQuestion < quizData.length) {
      showQuestion();
    } else {
      showResults();
    }
  };
  function showResults() {
    $id('pqQuizScreen').classList.add('pq-hidden');
    $id('pqResultScreen').classList.remove('pq-hidden');
    var total = quizData.length;
    var percentage = Math.round((score / total) * 100);
    $id('pqCorrectCount').textContent = score;
    $id('pqPercentage').textContent = percentage;
    var remarksEl = $id('pqRemarks');
    var remarksText = '';
    var remarksClass = '';
    if (percentage >= 80) {
      remarksText = '🌟 Excellent! Outstanding performance!';
      remarksClass = 'pq-excellent';
    } else if (percentage >= 60) {
      remarksText = '👍 Good Job! Well done!';
      remarksClass = 'pq-good';
    } else if (percentage >= 40) {
      remarksText = '😐 Average. Keep practicing!';
      remarksClass = 'pq-average';
    } else {
      remarksText = '💪 Needs Improvement. Try again!';
      remarksClass = 'pq-poor';
    }
    remarksEl.textContent = remarksText;
    remarksEl.className = 'pq-remarks ' + remarksClass;
  }
  window.pqRestartQuiz = function() {
    $id('pqResultScreen').classList.add('pq-hidden');
    $id('pqStartScreen').classList.remove('pq-hidden');
  };
  widget.addEventListener('contextmenu', function(e) {
    e.preventDefault();
  });
  loadBundle();
})();
